get_dashboard_section.code:
final response = await client.dashboardSections
    .getDashboardSection('blog', queryParams: {'duration': 'last_7_days'});
final section = response.map as Map;
print(section['comments_to_moderate']);
for (final row in section['most_viewed_posts'] as List) {
  final post = (row as Map)['post'] as Map;
  print('${post['name']} ${row['views']}');
}
